CREATE TABLE "public"."backorders" (
  "id"           bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "job_id"       bigint                   NOT NULL,
  "date_entered" date                     DEFAULT CURRENT_DATE,
  "due_date"     date,
  "comments"     text,
  "complete"     boolean                  NOT NULL DEFAULT false,
  "created_at"   timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"   timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "backorders_pkey" PRIMARY KEY (id),
  CONSTRAINT "backorders_job_id_fkey" FOREIGN KEY (job_id) REFERENCES public.jobs(id) ON DELETE CASCADE
);

ALTER TABLE "public"."backorders"
  ENABLE ROW LEVEL SECURITY;

CREATE TRIGGER set_updated_at
  BEFORE UPDATE ON public.backorders
  FOR EACH ROW
  EXECUTE FUNCTION public.handle_updated_at();

CREATE POLICY "Enable delete for admin only" ON "public"."backorders"
  FOR DELETE
  TO PUBLIC
  USING ((public.clerk_user_role() = 'admin'::text));

CREATE POLICY "Enable insert for backorder editors" ON "public"."backorders"
  FOR INSERT
  TO PUBLIC
  WITH CHECK ((public.clerk_user_role() = ANY (ARRAY['admin'::text, 'scheduler'::text, 'installation'::text, 'service'::text, 'plant'::text])));

CREATE POLICY "Enable read access for authenticated users" ON "public"."backorders"
  FOR SELECT
  TO PUBLIC
  USING ((auth.role() = 'authenticated'::text));

CREATE POLICY "Enable update for backorder editors" ON "public"."backorders"
  FOR UPDATE
  TO PUBLIC
  USING ((public.clerk_user_role() = ANY (ARRAY['admin'::text, 'scheduler'::text, 'installation'::text, 'service'::text, 'plant'::text])))
  WITH CHECK ((public.clerk_user_role() = ANY (ARRAY['admin'::text, 'scheduler'::text, 'installation'::text, 'service'::text, 'plant'::text])));

REVOKE ALL ON SEQUENCE "public"."backorders_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."backorders_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."backorders_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."backorders_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."backorders_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."backorders_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."backorders_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."backorders_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."backorders" TO "anon", "authenticated";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."backorders" TO "service_role";

REVOKE ALL ON TABLE "public"."backorders" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."backorders" TO "postgres";
